import {studioBusiness,studioTypes} from './studio-business.js';
import {getLanguage} from './i18n.js';
export function websiteUi({state,api,esc,button,openModal,closeModal,render,toast,resourceHeaders}) {
 let data=null,studio='',tab='chat',dirty=false,busy=false,message='',source=null,portrait='',pendingPrompt='',galleryOpen=false,previewTemplate='',sourceFile='index.html',previewChannel='',previewReport=null,device='desktop',chatDraft='',codeView=null,codeFilename='',codeStates={},projectQuotes=null,businessFilter='',styleFilter='all',publishTab='publish',publishChecks=null,materialsTab='projects',selectedPage='home',editScope='page',sourceScope='page';
 const freeze=value=>document.querySelectorAll('.workspace,.website-workspace,.website-studio,.modal').forEach(el=>{el.inert=value;el.setAttribute('aria-busy',String(value));});
 const copy=v=>structuredClone(v),uid=()=>crypto.randomUUID().replaceAll('-','');
 const btn=(label,act,kind='',extra='')=>button(label,'website-'+act,kind,extra);
 const field=(label,name,value,max=160,area=false)=>`<label>${label}${area?`<textarea rows="4" name="${name}" maxlength="${max}">${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" maxlength="${max}">`}</label>`;
 const footer=label=>`<div class="modal-footer">${button('Cancel','close-modal','ghost')}<button class="button primary" type="submit">${label}</button></div>`;
 const endpoint=(action,params={})=>'/api.php?'+new URLSearchParams({action,website_studio:state.studio.id,...params});
 const asset=id=>endpoint('website_asset',{id});
 async function load(){destroyCode();codeStates={};const sid=state.studio.id;const result=await api('website');if(state.studio.id!==sid)return;data=result;studio=sid;selectedPage='home';sourceScope='page';editScope='page';businessFilter=studioBusiness(state.studio?.business_type).id;styleFilter='all';dirty=false;tab='chat';chatDraft='';if(new URLSearchParams(location.search).get('website_checkout')==='success'){message='Confirming your payment…';data=await api('website_refresh_billing');message=data.billing.active?'Website activated. You can now publish.':'Payment is processing. Use Check payment to refresh.';}}
 function accept(result){if(result.studio_id!==state.studio.id)return;data=result;if(!enabledPages().some(p=>p.id===selectedPage))selectedPage='home';dirty=false;render();}
 async function save(){if(!dirty)return;accept(await api('website_save',{draft:data.draft,revision:data.revision}));}
 function destroyCode(){if(codeView){codeStates[codeFilename]=codeView.state;codeView.destroy();codeView=null;}}
 function active(){return !!state.user&&!state.client&&state.tab==='website'&&state.websiteEditing&&data?.draft.started&&studio===state.studio?.id;}
 function page(){
  destroyCode();if(!data||studio!==state.studio.id)return '<p>Opening your website…</p>';
  if(!data.draft.started)return welcome();
  if(active())return editorPage();
  return `<section class="website-dashboard"><div class="page-heading"><div><p class="website-eyebrow">YOUR STUDIO WEBSITE</p><h1>A home for your work.</h1><p class="muted">Shape your next chapter. Publish when it feels right.</p></div><div class="website-dashboard-top-actions">${btn('Edit website ↗','enter','ghost')}${btn(data.live?'Publish changes':'Publish website','publish','primary')}</div></div><div class="website-dashboard-grid"><div class="website-dashboard-preview"><iframe title="Saved website preview" tabindex="-1" sandbox="" src="${esc(endpoint('website_preview',{v:data.revision}))}"></iframe></div><aside class="website-dashboard-details"><span class="tag">${data.live?'Website published':'Private draft'}</span><h2>${esc(data.draft.name)}</h2><p>Your website changes only when you publish a new version.</p><div class="website-dashboard-actions">${data.live?`<a class="button ghost" href="${esc(data.url)}" target="_blank" rel="noopener">View live website ↗</a>`:''}</div><hr><p>Try a different direction</p>${btn('Browse starting designs','gallery','ghost')}${btn('Start from scratch','reset','ghost')}</aside></div></section>`;
 }
 const pageFile=(id,ext='html')=>id==='home'&&ext==='html'?'index.html':`pages/${id}.${ext}`;
 const enabledPages=()=>data.draft.pages.filter(p=>p.kind!=='project'||data.draft.projects.some(project=>project.id===p.project&&project.included));
 const currentPage=()=>data.draft.pages.find(p=>p.id===selectedPage)||data.draft.pages[0];
 const sharedLayout=()=>Object.hasOwn(data.draft.files,'header.html');
 function editableFiles(){return !sharedLayout()?['index.html','styles.css','script.js']:sourceScope==='shared'?['header.html','footer.html','styles.css','script.js']:['html','css','js'].map(ext=>pageFile(selectedPage,ext));}
 function pageToolbar(){return `<div class="website-page-toolbar"><label>Page<select data-website-page aria-label="Website page">${enabledPages().map(p=>`<option value="${p.id}" ${selectedPage===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div>${btn('Add page','add-page','small')}${btn('Manage pages','pages','small ghost')}</div></div>`;}
 async function selectPage(id,fragment=''){if(!enabledPages().some(p=>p.id===id))return;await save();destroyCode();selectedPage=id;sourceScope='page';sourceFile=pageFile(id);render();const frame=document.querySelector('.website-preview iframe');if(frame&&fragment)frame.src+='#'+encodeURIComponent(fragment);}
 function managePages(){openModal('Your website pages',`<div class="website-pages-dialog"><div class="website-materials-toolbar"><p>Every page shares your website’s header, footer and design. Change the order here to arrange your menu.</p>${btn('Add page','add-page','primary small')}</div><div class="website-page-list">${data.draft.pages.map((p,i)=>`<article class="website-page-card"><div><h3>${esc(p.name)}</h3><p>/${esc(p.slug)}${p.slug?'/':''}</p><small>${enabledPages().some(a=>a.id===p.id)?p.navigation?'In navigation':'Hidden from navigation':'Project hidden from website'}${p.kind==='project'?' · Connected project':''}</small></div><div class="website-page-actions">${btn('Open','open-page','small',`data-id="${p.id}" ${enabledPages().some(a=>a.id===p.id)?'':'disabled'}`)}${btn('Page details','page-details','small ghost',`data-id="${p.id}"`)}${p.kind!=='project'?btn('Duplicate','duplicate-page','small ghost',`data-id="${p.id}"`):''}${btn('↑','move-page','small ghost',`data-id="${p.id}" data-direction="-1" aria-label="Move ${esc(p.name)} up" ${i?'':'disabled'}`)}${btn('↓','move-page','small ghost',`data-id="${p.id}" data-direction="1" aria-label="Move ${esc(p.name)} down" ${i===data.draft.pages.length-1?'disabled':''}`)}${p.id!=='home'?btn('Delete','delete-page','small ghost',`data-id="${p.id}"`):''}</div></article>`).join('')}</div><div class="modal-footer">${button('Done','close-modal','ghost')}</div></div>`,true);}
 const slugify=value=>value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
 function pageForm(operation='add',id='',project=''){
  const p=data.draft.pages.find(p=>p.id===id),item=data.draft.projects.find(p=>p.id===project),name=operation==='update'?p.name:operation==='duplicate'?p.name+' copy':item?.title||'About',slug=operation==='update'?p.slug:item?'work/'+slugify(name):slugify(name);
  openModal(operation==='update'?'Page details':operation==='duplicate'?'Duplicate page':'Add a page',`<form data-form="website-page" data-operation="${operation}" data-id="${id}" data-project="${project}">${operation==='add'&&!project?`<label>Start with<select name="kind" data-website-page-kind><option value="about">About</option><option value="contact">Contact</option><option value="projects">Projects</option><option value="custom">Blank page</option></select></label><p class="form-hint">The Projects layout lists your connected projects automatically.</p>`:''}${field('Page name','name',name,120)}${id==='home'&&operation==='update'?'<p>Home is always at /.</p>':field('Page address','slug',slug,120)}<p class="form-hint">${project?'This page uses your reviewed project text, images and testimonials. Update them in your website library.':'Addresses look like /contact/ or /work/our-story/.'}</p><label class="check-label"><input type="checkbox" name="navigation" ${operation==='update'?p.navigation?'checked':'':project?'':'checked'}> Show in navigation</label>${footer(operation==='update'?'Save page details':'Create page')}</form>`);
 }
 async function changePage(values){await save();const result=await api('website_page',{...values,revision:data.revision});destroyCode();selectedPage=result.page;sourceScope='page';sourceFile=pageFile(selectedPage);accept(result.website);return result;}
 function editorPage(){
  previewChannel=uid();previewReport=null;
  return `<main class="website-studio" id="main" ${busy?'inert aria-busy="true"':''}><header class="website-editor-top"><div class="website-editor-identity">${btn('← Back to studio','leave','small ghost')}<span>${esc(data.draft.name)}</span></div><div class="website-device-switch" role="group" aria-label="Preview size">${btn('Desktop','device','small '+(device==='desktop'?'active':''),`data-size="desktop" aria-pressed="${device==='desktop'}"`)}${btn('Mobile','device','small '+(device==='mobile'?'active':''),`data-size="mobile" aria-pressed="${device==='mobile'}"`)}</div><div class="website-editor-actions">${btn('Add your projects & testimonials','manage-projects','primary small')}</div></header><div class="website-editor-layout ${tab==='source'?'source-mode':''}"><section class="website-preview ${device==='mobile'?'mobile':''}" aria-label="Website preview">${pageToolbar()}<div class="website-preview-canvas"><iframe title="Your website draft" sandbox="allow-scripts allow-popups" src="${esc(endpoint('website_preview',{v:data.revision,channel:previewChannel,page:selectedPage}))}"></iframe></div><footer><span class="website-preview-health" role="status">Checking preview…</span><span>Private draft</span></footer></section><aside class="website-editor-panel"><nav class="website-editor-panelbar" aria-label="Editing tools"><div>${btn('Chat','tab',tab==='chat'?'active':'ghost',`data-tab="chat" aria-pressed="${tab==='chat'}"`)}${btn('Code','tab',tab==='source'?'active':'ghost',`data-tab="source" aria-pressed="${tab==='source'}"`)}</div><div>${btn('Undo','undo','small ghost',data.can_undo?'':'disabled')}${btn('Save draft','save','small',dirty?'':'disabled')}</div></nav><div class="website-status" role="status"><span>${dirty?'Unsaved changes · Save to refresh preview':'Draft saved'}</span></div><div class="website-editor-panel-content">${tab==='source'?sourcePanel(data.draft):chatPanel(data.draft)}</div></aside></div></main>`;
 }
 async function afterRender(){
  const host=document.querySelector('[data-website-code-host]');if(!host||!active()||tab!=='source')return;
  try{const {mountEditor}=await import('./vendor/website-editor.js');if(!host.isConnected||codeView)return;const file=sourceFile,fresh=!codeStates[file]||codeStates[file].doc.toString()!==data.draft.files[file];const value=data.draft.files[file];let formatted;if(fresh){try{const {formatSource}=await import('./vendor/website-formatter.js');formatted=await formatSource(file,value);}catch{}}if(!host.isConnected||codeView||data.draft.files[file]!==value)return;codeFilename=file;host.replaceChildren();codeView=mountEditor(host,{filename:file,value,formatted,state:codeStates[file],onChange:value=>updateSource(file,value),onFormat:()=>{if(!busy)action('website-format-source',document.querySelector('[data-action="website-format-source"]')).catch(e=>toast(e.message));},onSave:()=>{if(!busy)action('website-save',document.querySelector('[data-action="website-save"]')).catch(e=>toast(e.message));}});}catch(e){host.innerHTML=`<label>${sourceFile}<textarea class="website-code" data-website-file="${sourceFile}" aria-label="${sourceFile} source">${esc(data.draft.files[sourceFile])}</textarea></label>`;toast('The code editor could not load. Plain-text editing is available.');}
 }
 function updateSource(file,value){data.draft.files[file]=value;dirty=true;const status=document.querySelector('.website-status span');if(status)status.textContent='Unsaved changes · Save to refresh preview';document.querySelectorAll('[data-action="website-save"]').forEach(b=>b.disabled=false);}
 function switchPanel(next){destroyCode();tab=next;const layout=document.querySelector('.website-editor-layout');if(!layout){render();return;}layout.classList.toggle('source-mode',tab==='source');document.querySelectorAll('[data-action="website-tab"]').forEach(b=>{const selected=b.dataset.tab===tab;b.classList.toggle('active',selected);b.classList.toggle('ghost',!selected);b.setAttribute('aria-pressed',String(selected));});document.querySelector('.website-editor-panel-content').innerHTML=tab==='source'?sourcePanel(data.draft):chatPanel(data.draft);afterRender();}
 const wt=(en,nl)=>getLanguage()==='nl'?nl:en;
 const templateStyles=[['all','All styles','Alle stijlen'],['modern','Modern','Modern'],['classic','Classic','Klassiek'],['minimal','Minimal','Minimalistisch'],['editorial','Editorial','Redactioneel'],['organic','Organic','Organisch'],['experimental','Experimental','Experimenteel']];
 function filteredTemplates(){return data.templates.filter(t=>t.id==='blank'||((businessFilter==='all'||t.business_types.includes(businessFilter))&&(styleFilter==='all'||t.styles.includes(styleFilter)))).sort((a,b)=>Number(a.id==='blank')-Number(b.id==='blank'));}
 function galleryFilters(){return `<div class="website-gallery-filters"><label>${wt('Business type','Type bedrijf')}<select data-website-filter="business"><option value="all" ${businessFilter==='all'?'selected':''}>${wt('All businesses','Alle bedrijven')}</option>${studioTypes.map(b=>`<option value="${b.id}" ${businessFilter===b.id?'selected':''}>${esc(studioBusiness(b.id).label)}</option>`).join('')}</select></label><div class="website-style-filters" role="group" aria-label="${wt('Design style','Ontwerpstijl')}">${templateStyles.map(([id,en,nl])=>btn(wt(en,nl),'filter-style','small '+(styleFilter===id?'active':'ghost'),`data-style="${id}" aria-pressed="${styleFilter===id}"`)).join('')}</div><p class="website-gallery-count" role="status">${filteredTemplates().length} ${wt('starting points','startpunten')}</p></div>`;}
 function welcome(){const b=studioBusiness(state.studio?.business_type);return `<section class="website-welcome"><div class="website-welcome-copy"><p class="website-eyebrow">${wt('YOUR STUDIO, OUT IN THE WORLD','JOUW STUDIO, KLAAR VOOR DE WERELD')}</p><h1>${wt('Good work deserves<br>a beautiful home.','Mooi werk verdient<br>een mooie plek.')}</h1><p>${wt('Start with a design you love. Make it entirely your own, simply by describing what you have in mind.','Begin met een ontwerp dat je aanspreekt. Maak het helemaal eigen door te vertellen wat je voor ogen hebt.')}</p><div class="row">${btn(wt('Find your starting point ↗','Vind jouw startpunt ↗'),'gallery','primary')}</div><span>${wt('Starting designs selected for','Startontwerpen geselecteerd voor')} ${esc(b.label.toLocaleLowerCase())}.</span></div><div class="website-welcome-art" aria-hidden="true"><div class="website-cover-frame"><small>${esc(b.label)}</small><h2>${esc(b.headline)}</h2><img src="${b.image}" alt=""><span>${esc(b.description)}</span></div><div class="website-cover-note">${wt('Your story.<br>Your point of view.','Jouw verhaal.<br>Jouw blik.')}</div></div></section>`;}

 function chatPanel(d){return `<section class="website-chat"><div class="row"><h2>Make it yours.</h2></div><p>Describe any change: a new layout, your updated address, an image gallery, or a project you’d like to add.</p><div class="website-conversation">${(d.conversation||[]).map(m=>`<div class="website-chat-bubble ${m.role}"><small>${m.role==='user'?'You':'Website assistant'}</small><p>${esc(m.text)}</p></div>`).join('')}</div><form data-form="website-chat">${sharedLayout()?`<label>Edit scope<select name="scope" data-website-edit-scope><option value="page" ${editScope==='page'?'selected':''}>This page · ${esc(currentPage().name)}</option><option value="shared" ${editScope==='shared'?'selected':''}>Shared design · all pages</option></select></label>`:''}<label for="website-prompt">What would you like to change?</label><textarea id="website-prompt" name="prompt" rows="5" maxlength="4000" placeholder="Make this feel like an architectural magazine…" ${data.ai?'':'disabled'} required>${esc(chatDraft)}</textarea><button class="button primary" type="submit" ${data.ai?'':'disabled'}>Update my draft ↗</button><small>${data.ai?data.ai_remaining+' edits left this month':'AI is not connected. You can edit the files in Code.'}</small></form><div class="website-prompt-ideas">${['Make the layout more editorial','Add a project from StudioDeck','Update my studio address'].map(p=>btn(esc(p),'prompt','small ghost',`data-prompt="${esc(p)}"`)).join('')}</div><p class="website-chat-message" role="status">${esc(message)}</p></section>`;}
 function sourcePanel(d){const files=editableFiles();if(!files.includes(sourceFile))sourceFile=files[0];return `<section class="website-source-panel">${sharedLayout()?`<div class="website-code-scope" role="group" aria-label="Code scope">${btn(esc(currentPage().name),'source-scope','small '+(sourceScope==='page'?'active':'ghost'),'data-scope="page"')}${btn('Shared design','source-scope','small '+(sourceScope==='shared'?'active':'ghost'),'data-scope="shared"')}</div><p class="form-hint">${sourceScope==='shared'?'Changes here apply to every page. Menu links are managed in Pages.':'Changes here apply to this page. Keep the shared header and footer markers.'}</p>`:''}<div class="website-file-tabs" role="group" aria-label="Website files">${files.map(f=>btn(sharedLayout()&&sourceScope==='page'?({'html':'Page HTML','css':'Page CSS','js':'Page JavaScript'}[f.split('.').pop()]):f,'file','small '+(sourceFile===f?'active':'ghost'),`data-file="${f}" aria-pressed="${sourceFile===f}"`)).join('')}</div><div class="website-code-host" data-website-code-host><p>Opening code editor…</p></div><footer class="website-source-footer"><span>HTML / CSS / JavaScript · Ctrl/⌘ S to save · Ctrl/⌘ F to find · Shift+Alt+F to format</span><div class="row wrap">${btn('Save & preview','save','small primary')}${btn('Format code','format-source','small ghost','title="Format code (Shift+Alt+F)"')}${btn('Copy file','copy-source','small ghost')}<label class="website-file-import button small ghost">Import files<input type="file" data-website-files multiple accept=".html,.css,.js"></label>${btn('Images','images','small ghost')}</div>${[...(data.checks?.errors||[]),...(data.checks?.warnings||[])].map(m=>`<p class="form-hint">${esc(m)}</p>`).join('')}</footer></section>`;}
 function imageLibrary(){return `<p>Use these paths in your source. Images are optimized when published.</p>${[...new Set([data.draft.hero_asset,data.draft.logo,...data.draft.projects.flatMap(p=>p.images.map(im=>im.asset)),...data.draft.testimonials.map(t=>t.photo)].filter(Boolean))].map(id=>`<div class="website-asset-reference"><img src="${esc(asset(id))}" alt=""><code>assets/${id}.webp</code></div>`).join('')}`;}
 function manageProjects(next=materialsTab){
  materialsTab=next;const isProjects=materialsTab==='projects';
  openModal('Your projects & testimonials',`<div class="website-materials-dialog"><div class="website-materials-tabs" role="tablist" aria-label="Website content">${[['projects','Projects'],['testimonials','Testimonials']].map(([id,label])=>btn(`${label} <span aria-hidden="true">${data.draft[id].length}</span>`,'materials-tab',materialsTab===id?'active':'ghost',`data-tab="${id}" role="tab" id="website-materials-tab-${id}" aria-selected="${materialsTab===id}" aria-controls="website-materials-panel" tabindex="${materialsTab===id?'0':'-1'}"`)).join('')}</div><div class="website-materials-panel" id="website-materials-panel" role="tabpanel" aria-labelledby="website-materials-tab-${materialsTab}"><div class="website-materials-toolbar"><p>${isProjects?'Choose the work you want to share on your website.':'Share the words of the people you work with.'}</p>${isProjects?btn('Add project','choose-project','primary small'):btn('Add testimonial','testimonial','primary small')}</div><div class="website-materials-list" tabindex="0" aria-label="${isProjects?'Connected projects':'Website testimonials'}">${isProjects?projects(data.draft):testimonials(data.draft)}</div></div><div class="modal-footer">${button('Done','close-modal','ghost')}</div></div>`,true);
 }
 function renderGallery(){document.getElementById('website-gallery')?.remove();if(!galleryOpen)return;const selected=data.templates.find(t=>t.id===previewTemplate);const node=document.createElement('div');node.id='website-gallery';node.className='website-gallery-overlay';node.setAttribute('role','dialog');node.setAttribute('aria-modal','true');node.setAttribute('aria-label',selected?selected.name+' full-screen preview':'Choose your starting point');node.innerHTML=selected?`<header><div><strong>${esc(selected.name)}</strong><span>${esc(selected.description)} · Example content</span></div><div class="row">${btn('All designs','gallery-back','ghost')}${btn('Use this starting point','choose-template','primary',`data-template="${selected.id}"`)}${btn('Close','gallery-close','ghost')}</div></header><iframe class="website-full-example" title="${esc(selected.name)} full-screen example" sandbox="allow-scripts" src="${esc(endpoint('website_template_preview',{template:selected.id}))}"></iframe>`:`<header><div><p class="website-eyebrow">YOUR NEXT CHAPTER</p><h2>Find your starting point.</h2><p>${wt('Explore every design. Find a style that feels like you.','Ontdek alle ontwerpen. Vind een stijl die bij je past.')}</p></div>${btn('Close','gallery-close','ghost')}</header>${galleryFilters()}<div class="website-template-grid">${filteredTemplates().map(t=>`<article class="website-example-card ${t.tone}"><button class="website-example-preview" data-action="website-example" data-template="${t.id}" aria-label="Preview ${esc(t.name)} full screen"><iframe title="${esc(t.name)} thumbnail" tabindex="-1" loading="lazy" sandbox="" src="${esc(endpoint('website_template_preview',{template:t.id}))}"></iframe><span>Explore full screen ↗</span></button><div class="website-example-caption"><div><h3>${esc(t.name)}</h3>${t.recommended?`<span class="website-recommendation">${wt('Selected for your studio','Geselecteerd voor jouw studio')}</span>`:''}<p>${esc(t.description)}</p><div class="website-template-tags">${t.styles.map(id=>`<span>${wt(...templateStyles.find(style=>style[0]===id).slice(1))}</span>`).join('')}</div></div>${btn('Choose','choose-template','small',`data-template="${t.id}"`)}</div></article>`).join('')}</div>`;document.body.append(node);node.querySelector('button')?.focus();}
 async function chooseTemplate(id){await save();galleryOpen=false;renderGallery();if(data.draft.started){openModal('Use a new starting point?',`<p>This replaces the draft design and keeps your project materials. Your current live website stays unchanged. You can undo this choice.</p><div class="modal-footer">${button('Keep my design','close-modal','ghost')}${btn('Replace draft design','start','primary',`data-template="${id}"`)}</div>`);}else{state.websiteEditing=true;accept(await api('website_start',{template:id,revision:data.revision}));tab='chat';render();}}
 async function checkViewport(width,page){return new Promise(resolve=>{const channel=uid(),frame=document.createElement('iframe');frame.sandbox='allow-scripts';frame.style.cssText=`position:fixed;left:-20000px;top:0;width:${width}px;height:900px;border:0`;frame.title='Website publication check';let timer;const done=result=>{clearTimeout(timer);window.removeEventListener('message',receive);frame.remove();resolve({...result,width,page:page.name});};const receive=e=>{if(e.source===frame.contentWindow&&e.data?.type==='website-preview-report'&&e.data.channel===channel)done(e.data);};window.addEventListener('message',receive);timer=setTimeout(()=>done({errors:['Preview checks timed out. Please try again.']}),12000);frame.src=endpoint('website_preview',{v:data.revision,channel,page:page.id});document.body.append(frame);});}
 function projects(d){return d.projects.map(p=>`<article class="website-material-card"><div class="website-material-summary">${p.images[0]?`<img class="website-material-cover" src="${esc(asset(p.images[0].asset))}" alt="" loading="lazy">`:'<span class="website-material-placeholder" aria-hidden="true">↗</span>'}<div><h3>${esc(p.title)}</h3><p>${p.images.length} ${p.images.length===1?'photo':'photos'}${p.category?' · '+esc(p.category):''}</p><span class="website-material-status ${p.included?'included':''}">${p.included?'Included in draft':'Hidden from draft'}</span></div></div><div class="website-material-actions">${btn('Edit','edit-project','small',`data-id="${p.id}"`)}${btn(data.draft.pages.some(page=>page.project===p.id)?'Open project page':'Create project page','project-page','small ghost',`data-id="${p.id}" ${p.included?'':'disabled'}`)}${btn(p.included?'Hide':'Include','toggle-project','small ghost',`data-id="${p.id}"`)}${data.projects.some(s=>s.id===p.source_id)?`${btn('Update from project','import','small ghost',`data-id="${p.source_id}"`)}${btn('Project testimonials','project-testimonials','small ghost',`data-project="${p.source_id}"`)}`:'<span class="website-material-note">Independent website copy</span>'}</div></article>`).join('')||'<div class="website-material-empty"><h3>Your work belongs here.</h3><p>Add a project and choose the photos and details to share.</p></div>';}
 function testimonials(d){return d.testimonials.map(t=>`<article class="website-material-card"><div class="website-material-summary">${t.photo?`<img class="website-material-avatar" src="${esc(asset(t.photo))}" alt="" loading="lazy">`:'<span class="website-material-placeholder quote" aria-hidden="true">“</span>'}<div><h3>${esc(t.name)}</h3>${t.title?`<p>${esc(t.title)}</p>`:''}<span class="website-material-status ${t.approved?'included':''}">${t.approved?'Approved for publication':'Private draft'}</span></div></div><blockquote class="website-material-quote">${esc(t.content)}</blockquote><p class="website-material-note">${esc(d.projects.find(p=>p.id===t.project)?.title||'Studio testimonial')}</p><div class="website-material-actions">${btn('Edit','testimonial','small',`data-id="${t.id}"`)}${btn('Remove','remove-testimonial','small ghost',`data-id="${t.id}"`)}</div></article>`).join('')||'<div class="website-material-empty"><h3>Let your clients tell the story.</h3><p>Add a testimonial, or select approved quotes when adding a project.</p></div>';}
 function publishingContent(){
  const domain=data.domain;
  if(publishTab==='domain')return `<form data-form="website-domain">${field('Custom domain','name',domain.name,253)}<p class="form-hint">Use a www address, such as www.yourstudio.com.</p><button class="button" type="submit">${domain.name?'Check connection':'Set domain'}</button></form>${domain.name?`<div class="website-dns"><p>${domain.verified?'Domain verified. Publish to use this address.':'Add these DNS records, then check the connection.'}</p><dl><dt>CNAME · ${esc(domain.name)}</dt><dd>${esc(domain.target||'Hosting connection not configured')}</dd><dt>TXT · _studiodeck.${esc(domain.name)}</dt><dd>${esc(domain.token)}</dd></dl><p class="form-hint">Keep your existing email DNS records. DNS changes can take time to appear.</p></div>`:''}`;
  if(publishTab==='versions')return `<div class="website-version-heading"><p>Restore a version to your draft, then publish when ready.</p>${data.live?`<a class="button small ghost" href="${esc(endpoint('website_export'))}">Download live website (.zip)</a>`:''}</div><ol class="website-version-list">${data.releases.map((r,i)=>`<li class="website-version ${r.id===data.live?.release?'current':''}"><div><div class="website-version-title"><strong>Version ${data.releases.length-i}</strong>${r.id===data.live?.release?'<span class="tag">Live</span>':''}</div><time datetime="${esc(r.created_at)}">${esc(new Date(r.created_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</time></div>${btn('Restore to draft','restore','small ghost',`data-id="${r.id}"`)}</li>`).join('')||'<li class="website-versions-empty">No published versions yet. Your first publication will appear here.</li>'}</ol>`;
  return `<div class="website-publish-summary"><span class="tag">${data.live?'Published':'Private draft'}</span><h3>${esc(data.draft.name)}</h3><p class="website-url">${data.live?`<a href="${esc(data.url)}" target="_blank" rel="noopener">${esc(data.url)} ↗</a>`:esc(data.url)}</p></div><p>${data.live?'Publish your saved draft to update the live website.':'Publish your saved draft at this address.'}</p><div class="website-publish-checks" role="status">${publishChecks?.checking?'<p>Checking desktop and mobile previews…</p>':publishChecks?`${publishChecks.errors.length?'<p>Fix these issues in the editor before publishing.</p>':'<p>Ready to publish.</p>'}${publishChecks.errors.map(error=>`<p class="form-error">${esc(error)}</p>`).join('')}${publishChecks.warnings.map(warning=>`<p class="form-hint">${esc(warning)}</p>`).join('')}`:''}</div>`;
 }
 function showPublishing(next=publishTab){
  publishTab=next;
  openModal('Publish website',`<div class="website-publish-dialog"><div class="website-publish-tabs" role="tablist" aria-label="Website publishing">${[['publish','Publish'],['domain','Domain'],['versions','Published versions']].map(([id,label])=>btn(label,'publish-tab',publishTab===id?'active':'ghost',`data-tab="${id}" role="tab" id="website-publish-tab-${id}" aria-selected="${publishTab===id}" aria-controls="website-publish-panel" tabindex="${publishTab===id?'0':'-1'}"`)).join('')}</div><div class="website-publish-content" id="website-publish-panel" role="tabpanel" aria-labelledby="website-publish-tab-${publishTab}" tabindex="0">${publishingContent()}</div><div class="modal-footer">${button('Close','close-modal','ghost')}${publishTab==='publish'?(publishChecks?btn('Publish now','confirm-publish','primary',publishChecks.checking||publishChecks.errors.length?'disabled':''):btn('Review & publish','review-publish','primary')):''}</div></div>`,true);
 }
 async function reviewPublication(){
  await save();publishChecks={checking:true,errors:[],warnings:[]};showPublishing('publish');const dialog=document.querySelector('.website-publish-dialog');dialog.inert=true;dialog.setAttribute('aria-busy','true');
  const checks=data.checks||{errors:[],warnings:[]};
  try{
   const results=[];if(!checks.errors.length)for(const page of enabledPages())results.push(...await Promise.all([checkViewport(390,page),checkViewport(1280,page)]));
   publishChecks={checking:false,revision:data.revision,errors:[...new Set([...checks.errors,...results.flatMap(r=>[...(r.errors||[]).map(error=>`${r.page} (${r.width}px): ${error}`),...(r.missingImages?[`${r.page}: Some images did not load.`]:[])])])],warnings:[...checks.warnings,...results.filter(r=>r.overflow).map(r=>`${r.page} overflows at ${r.width}px. Review this layout before publishing.`)]};
  }catch(error){publishChecks={checking:false,errors:[error.message],warnings:[]};}
  if(document.querySelector('.website-publish-dialog'))showPublishing();
 }
 async function importModal(pid,prompt=''){pendingPrompt=prompt;
  await save();source=await api('website_sources',{project_id:pid});const previous=data.draft.projects.find(p=>p.source_id===pid);
  openModal(previous?'Update public project copy':'Add project to website',`<form data-form="website-import"><div class="website-import-content"><p>Review the public copy and select photographs. Private documents, budgets, and client details are never included automatically.</p>${field('Public title','title',source.project.title,160)}${field('Public description','description',source.project.description,6000,true)}<p class="form-hint">Updating replaces this website project’s title, description, and selected gallery. Its page anchor and visibility are kept.</p><div class="website-source-grid">${source.images.map(im=>`<label class="website-source"><img loading="lazy" src="${esc(endpoint('website_source_image',{project_id:pid,id:im.id}))}" alt=""><span><input type="checkbox" name="image" value="${im.id}"> ${esc(im.title||'Project image')}</span><input name="alt_${im.id}" maxlength="250" placeholder="Describe this image for visitors" aria-label="Image description for ${esc(im.title)}" value="${esc(im.title)}"></label>`).join('')||'<p>No project photographs available. You can add images after importing.</p>'}</div><fieldset class="website-import-quotes"><legend>Project testimonials</legend><p class="form-hint">Select the approved quotes to copy onto this website.</p>${source.testimonials.filter(t=>Number(t.approved)).map(t=>`<label class="website-quote-choice"><input type="checkbox" name="testimonial" value="${t.id}" ${previous&&data.draft.testimonials.some(c=>c.project===previous.id&&c.source_testimonial===t.id)?'checked':''}><span><strong>${esc(t.name)}</strong><span>${esc(t.content)}</span></span></label>`).join('')||'<p>No approved testimonials yet. Add them in the project’s settings.</p>'}</fieldset></div>${footer(previous?'Update draft copy':'Add to draft')}</form>`,true);

 }
 function editProject(id){const p=data.draft.projects.find(p=>p.id===id);openModal('Website project',`<form data-form="website-project" data-id="${id}">${field('Public title','title',p.title,160)}${field('Public description','description',p.description,6000,true)}${field('Category','category',p.category,80)}${field('Public location (optional)','location',p.location,100)}<div class="website-edit-images">${p.images.map((im,n)=>`<div><img src="${esc(asset(im.asset))}" alt="">${field('Image description','alt_'+n,im.alt,250)}<label><input type="checkbox" name="remove_${n}"> Remove from gallery</label></div>`).join('')}</div><label>Add gallery images<input type="file" name="images" multiple accept="image/jpeg,image/png,image/webp"></label><p class="form-hint">The first image is the project cover. New photographs are added at the end.</p>${footer('Save public copy')}</form>`,true);}
 function testimonialModal(id){const t=data.draft.testimonials.find(t=>t.id===id)||{id:uid(),name:'',title:'',content:'',project:'',photo:'',video:'',placement:'both',approved:false};portrait=t.photo;openModal('Client testimonial',`<form data-form="website-testimonial" data-id="${t.id}">${field('Name','name',t.name,120)}${field('Title / role','title',t.title,120)}${field('Quote','content',t.content,2000,true)}${t.source_testimonial?`<input type="hidden" name="project" value="${t.project}"><p>Project: <strong>${esc(data.draft.projects.find(p=>p.id===t.project)?.title||'Project copy')}</strong></p>`:`<label>Project (optional)<select name="project"><option value="" ${!t.project?'selected':''}>Studio testimonial</option>${data.draft.projects.map(p=>`<option value="${p.id}" ${p.id===t.project?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>`}<label>Placement<select name="placement">${[['both','Home and project page'],['home','Home testimonials section'],['project','With this project']].map(([id,label])=>`<option value="${id}" ${id===t.placement?'selected':''}>${label}</option>`).join('')}</select></label>${field('YouTube video link (optional)','video',t.video,2048)}<label>Photo (optional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label>${portrait?'<label><input type="checkbox" name="remove_photo"> Remove current photo</label>':''}<label class="check-label"><input name="approved" type="checkbox" ${t.approved?'checked':''}> I have permission to publish this testimonial and its media.</label>${footer('Save testimonial')}</form>`);}
 async function projectQuotesModal(pid){projectQuotes=await api('project_testimonials',{project_id:pid});showProjectQuotes();}
 function showProjectQuotes(){openModal('Testimonials · '+projectQuotes.project.name,`<p>These testimonials belong to this project. Website copies are updated only when you select them in the website editor.</p>${btn('Add testimonial','edit-project-testimonial','primary')}<div class="website-items">${projectQuotes.testimonials.map(t=>`<article class="website-item"><div><strong>${esc(t.name)}</strong><p>${esc(t.content)}</p><small>${Number(t.approved)?'Permission to publish confirmed':'Not approved for publication'}</small></div><div>${btn('Edit','edit-project-testimonial','small',`data-id="${t.id}"`)}${btn('Remove','delete-project-testimonial','small ghost',`data-id="${t.id}"`)}</div></article>`).join('')||'<p>No testimonials for this project yet.</p>'}</div>`,true);}
 function projectQuoteForm(id){const t=projectQuotes.testimonials.find(t=>t.id===id)||{id:'',revision:0,name:'',title:'',content:'',video:'',approved:0,has_photo:0};openModal(t.id?'Edit project testimonial':'Add project testimonial',`<form data-form="website-project-testimonial" data-id="${t.id}" data-revision="${t.revision}"><p>Project: <strong>${esc(projectQuotes.project.name)}</strong></p>${field('Name','name',t.name,120)}${field('Title / role','title',t.title,120)}${field('Quote','content',t.content,2000,true)}${field('YouTube video link (optional)','video',t.video,2048)}${Number(t.has_photo)?`<img class="website-testimonial-portrait" src="${esc(endpoint('project_testimonial_photo',{project_id:projectQuotes.project.id,id:t.id}))}" alt="${esc(t.name)}"><label><input type="checkbox" name="remove_photo"> Remove photo</label>`:''}<label>Photo (optional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="check-label"><input type="checkbox" name="approved" ${Number(t.approved)?'checked':''}> I have permission to publish this testimonial and its media.</label><p class="form-hint">Saving here does not change the website draft or live website.</p>${footer('Save testimonial')}</form>`);}
 async function encodedPhoto(file){if(file.size>20*1024*1024)throw Error('Choose an image smaller than 20 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});}
 async function upload(file){if(file.size>20*1024*1024)throw Error('Choose an image smaller than 20 MB.');const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});return (await api('website_upload',{data:encoded})).id;}
 async function action(a,el){
  if(busy)return;busy=true;freeze(true);el.disabled=true;
  try{
   const act=a.replace(/^website-?/,'');
   if(act==='project-testimonials'){await projectQuotesModal(el.dataset.project);return;}
   if(act==='edit-project-testimonial'){projectQuoteForm(el.dataset.id);return;}
   if(act==='delete-project-testimonial'){const t=projectQuotes.testimonials.find(t=>t.id===el.dataset.id);openModal('Remove project testimonial?',`<p>Remove this original testimonial? Existing website copies stay unchanged until explicitly updated.</p><div class="modal-footer">${button('Cancel','close-modal','ghost')}${btn('Remove testimonial','confirm-delete-project-testimonial','danger-text',`data-id="${t.id}" data-revision="${t.revision}"`)}</div>`);return;}
   if(act==='confirm-delete-project-testimonial'){projectQuotes=await api('project_testimonial_delete',{project_id:projectQuotes.project.id,id:el.dataset.id,revision:Number(el.dataset.revision)});showProjectQuotes();return;}
   if(!act||act==='open-project'){if(data&&studio===state.studio.id)await save();closeModal();state.data=null;state.present=false;state.tab='website';state.websiteEditing=false;await load();render();if(act==='open-project')await importModal(el.dataset.id);return;}
   if(!data||studio!==state.studio.id)await load();
   if(act==='enter'){closeModal();state.websiteEditing=true;tab='chat';render();}
   if(act==='leave'){await save();destroyCode();state.websiteEditing=false;render();}
   if(act==='manage-projects'){await save();manageProjects('projects');}
   if(act==='materials-tab'){manageProjects(el.dataset.tab);document.getElementById('website-materials-tab-'+materialsTab)?.focus();}
   if(act==='pages'){await save();managePages();}
   if(act==='add-page'){await save();pageForm();}
   if(act==='page-details'){await save();pageForm('update',el.dataset.id);}
   if(act==='duplicate-page'){await save();pageForm('duplicate',el.dataset.id);}
   if(act==='open-page'){closeModal();await selectPage(el.dataset.id);}
   if(act==='project-page'){await save();const p=data.draft.pages.find(p=>p.project===el.dataset.id);if(p){closeModal();await selectPage(p.id);}else pageForm('add','',el.dataset.id);}
   if(act==='move-page'){await changePage({operation:'move',id:el.dataset.id,direction:Number(el.dataset.direction)});managePages();}
   if(act==='delete-page'){const p=data.draft.pages.find(p=>p.id===el.dataset.id);openModal('Delete this page?',`<p>Remove ${esc(p.name)} from the draft? Links to it will go to Home. Connected projects and testimonials stay in your library. You can undo this change.</p><div class="modal-footer">${button('Cancel','close-modal','ghost')}${btn('Delete page','confirm-delete-page','danger-text',`data-id="${p.id}"`)}</div>`);}
   if(act==='confirm-delete-page'){await changePage({operation:'delete',id:el.dataset.id});managePages();}
   if(act==='source-scope'){sourceScope=el.dataset.scope;switchPanel('source');}
   if(act==='images')openModal('Website images',imageLibrary(),true);
   if(act==='reset'){openModal('Remove website and start from scratch?',`<p>This permanently removes your current website design, chat, website images, project copies, testimonials, and all saved versions. Your published website will be taken offline.</p><p>Your original StudioDeck projects stay safe. Your domain connection and Website subscription are kept; this does not cancel billing.</p><p>You’ll return to the welcome screen to choose a new starting point. This cannot be undone.</p><div class="modal-footer">${button('Keep my website','close-modal','ghost')}${btn('Remove website & start over','confirm-reset','danger-text')}</div>`);}
   if(act==='confirm-reset'){const result=await api('website_reset',{revision:data.revision,confirm:true});closeModal();galleryOpen=false;previewTemplate='';renderGallery();state.websiteEditing=false;tab='chat';sourceFile='index.html';chatDraft='';message='';source=null;portrait='';pendingPrompt='';accept(result);toast('Website removed. Choose a new starting point.');}
   if(act==='save'){await save();toast('Website draft saved.');}
   if(act==='tab')switchPanel(el.dataset.tab);
   if(act==='gallery'){await save();closeModal();galleryOpen=true;previewTemplate='';renderGallery();}
   if(act==='gallery-close'){galleryOpen=false;renderGallery();}
   if(act==='filter-style'){styleFilter=el.dataset.style;renderGallery();document.querySelector(`[data-style="${styleFilter}"]`)?.focus();}
   if(act==='gallery-back'){previewTemplate='';renderGallery();}
   if(act==='example'){previewTemplate=el.dataset.template;renderGallery();}
   if(act==='choose-template')await chooseTemplate(el.dataset.template);
   if(act==='start'){closeModal();state.websiteEditing=true;accept(await api('website_start',{template:el.dataset.template,revision:data.revision}));}
   if(act==='file'){sourceFile=el.dataset.file;switchPanel('source');}
   if(act==='format-source'){if(!codeView)throw Error('Wait for the code editor to load.');try{const {formatEditor}=await import('./vendor/website-editor.js');const result=await formatEditor(codeView,sourceFile);toast(result==='formatted'?'Code formatted. Save to update the preview.':result==='stale'?'Code changed while formatting. Try again.':'Code is already formatted.');}catch(error){throw Error('Could not format this file. '+error.message);}}
   if(act==='copy-source'){await navigator.clipboard.writeText(data.draft.files[sourceFile]);toast('Source copied.');}
   if(act==='prompt'){const input=document.getElementById('website-prompt');input.value=el.dataset.prompt;chatDraft=input.value;setTimeout(()=>input.focus(),0);}
   if(act==='device'){device=el.dataset.size;document.querySelector('.website-preview').classList.toggle('mobile',device==='mobile');document.querySelectorAll('[data-action="website-device"]').forEach(b=>{b.classList.toggle('active',b.dataset.size===device);b.setAttribute('aria-pressed',String(b.dataset.size===device));});}
   if(act==='section'){const i=Number(el.dataset.index),j=i+Number(el.dataset.direction);[data.draft.sections[i],data.draft.sections[j]]=[data.draft.sections[j],data.draft.sections[i]];dirty=true;await save();}
   if(act==='remove-logo'){data.draft.logo='';dirty=true;await save();}
   if(act==='choose-project'){await save();openModal('Add a project',`<p>Choose a project, then review the text, photographs and testimonials to include.</p><div class="website-project-picker">${data.projects.map(p=>btn(esc(p.name)+(p.archived?' · Archived':'')+(data.draft.projects.some(c=>c.source_id===p.id)?' · Already added':''),'import','',`data-id="${p.id}"`)).join('')||'<p>Create a project in StudioDeck first.</p>'}</div>`);}
   if(act==='import')await importModal(el.dataset.id);
   if(act==='edit-project'){await save();editProject(el.dataset.id);}
   if(act==='toggle-project'){data.draft.projects.find(p=>p.id===el.dataset.id).included=!data.draft.projects.find(p=>p.id===el.dataset.id).included;dirty=true;await save();manageProjects('projects');}
   if(act==='testimonial'){await save();testimonialModal(el.dataset.id);}
   if(act==='remove-testimonial'){data.draft.testimonials=data.draft.testimonials.filter(t=>t.id!==el.dataset.id);dirty=true;await save();manageProjects('testimonials');}
   if(act==='undo'){accept(await api('website_undo',{revision:data.revision}));}
   if(act==='publish'||act==='review-publish')await reviewPublication();
   if(act==='publish-tab'){showPublishing(el.dataset.tab);document.getElementById('website-publish-tab-'+publishTab)?.focus();}
   if(act==='confirm-publish'){if(!publishChecks||publishChecks.checking||publishChecks.errors.length||publishChecks.revision!==data.revision){await reviewPublication();return;}const result=await api('website_publish',{revision:data.revision});accept(result);publishChecks=null;showPublishing('versions');toast('Your website is published.');}
   if(act==='restore'){await save();accept(await api('website_restore',{release:el.dataset.id,revision:data.revision}));publishChecks=null;showPublishing('versions');toast('Earlier version restored to draft. Preview before publishing.');}
   if(act==='checkout'){await save();const result=await api('website_checkout');location.assign(result.url);}
   if(act==='refresh-billing'){accept(await api('website_refresh_billing'));toast(data.billing.active?'Website subscription active.':'Payment is not confirmed yet.');}
  }finally{busy=false;freeze(false);el.disabled=false;if(a==='website-format-source')codeView?.focus();}
 }
 async function submit(type,form){
  if(busy)return;busy=true;freeze(true);const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
  try{const values=Object.fromEntries(new FormData(form));
   if(type==='website-page'){await changePage({operation:form.dataset.operation,id:form.dataset.id,name:values.name,slug:values.slug||'',navigation:values.navigation==='on',kind:form.dataset.project?'project':values.kind||'custom',project:form.dataset.project});closeModal();toast('Page saved.');return;}
   if(type==='website-project-testimonial'){const file=form.elements.photo.files[0];projectQuotes=await api('project_testimonial_save',{project_id:projectQuotes.project.id,id:form.dataset.id,revision:Number(form.dataset.revision),name:values.name,title:values.title,content:values.content,video:values.video,approved:values.approved==='on',remove_photo:values.remove_photo==='on',...(file?{photo:await encodedPhoto(file)}:{})});showProjectQuotes();return;}
   if(type==='website-details'){await save();toast('Draft saved. Preview updated.');}
   if(type==='website-chat'){chatDraft=values.prompt;await save();message='Working on your draft…';toast(message);const result=await api('website_chat',{prompt:values.prompt,revision:data.revision,page:selectedPage,scope:editScope});message=result.message;chatDraft='';accept(result.website);if(result.project_id)await importModal(result.project_id,result.prompt);}
   if(type==='website-import'){const ids=new FormData(form).getAll('image');if(ids.length>20)throw Error('Select up to 20 images.');const result=await api('website_import',{project_id:source.project.id,revision:data.revision,title:values.title,description:values.description,testimonials:new FormData(form).getAll('testimonial'),images:ids.map(id=>({id,alt:values['alt_'+id]}))});closeModal();tab='chat';state.websiteEditing=!!result.draft.started;accept(result);if(pendingPrompt&&data.ai){const prompt=pendingPrompt;pendingPrompt='';try{const changed=await api('website_chat',{prompt:prompt+' Use the newly reviewed public project copy already in the library; integrate it into the current page.',revision:data.revision,page:selectedPage,scope:editScope});message=changed.message;tab='chat';accept(changed.website);}catch(e){message='The public project copy is saved. '+e.message;toast(message);render();}}}
   if(type==='website-project'){const next=copy(data.draft),p=next.projects.find(p=>p.id===form.dataset.id);for(const key of ['title','description','category','location'])p[key]=values[key];p.images=p.images.map((im,n)=>({...im,alt:values['alt_'+n],remove:values['remove_'+n]==='on'})).filter(im=>!im.remove);for(const file of form.elements.images.files){const asset=await upload(file);p.images.push({asset,alt:file.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ')});}const result=await api('website_save',{draft:next,revision:data.revision});closeModal();accept(result);}
   if(type==='website-testimonial'){const file=form.elements.photo.files[0];const t={id:form.dataset.id,source_testimonial:data.draft.testimonials.find(t=>t.id===form.dataset.id)?.source_testimonial||'',name:values.name,title:values.title,content:values.content,project:values.project,video:values.video,placement:values.placement,approved:values.approved==='on',photo:file?await upload(file):values.remove_photo==='on'?'':portrait};const next=copy(data.draft),index=next.testimonials.findIndex(x=>x.id===t.id);if(index<0)next.testimonials.push(t);else next.testimonials[index]=t;const result=await api('website_save',{draft:next,revision:data.revision});closeModal();accept(result);}
   if(type==='website-domain'){accept(await api('website_domain',{name:values.name}));publishChecks=null;showPublishing('domain');}
  }finally{busy=false;freeze(false);if(submit)submit.disabled=false;}
 }
 document.addEventListener('input',e=>{if(e.target.id==='website-prompt')chatDraft=e.target.value;if(e.target.name==='name'&&e.target.form?.dataset.form==='website-page'&&e.target.form.dataset.operation!=='update'&&!e.target.form.elements.slug.dataset.edited)e.target.form.elements.slug.value=(e.target.form.dataset.project?'work/':'')+slugify(e.target.value);if(e.target.name==='slug'&&e.target.form?.dataset.form==='website-page')e.target.dataset.edited='true';const file=e.target.dataset.websiteFile;if(data&&file)updateSource(file,e.target.value);});
 document.addEventListener('change',async e=>{if(e.target.hasAttribute('data-website-page')){if(busy)return;busy=true;freeze(true);try{await selectPage(e.target.value);}catch(error){toast(error.message);render();}finally{busy=false;freeze(false);}return;}if(e.target.hasAttribute('data-website-edit-scope')){editScope=e.target.value;return;}if(e.target.hasAttribute('data-website-page-kind')){const form=e.target.form,name={about:'About',contact:'Contact',projects:'Projects',custom:'New page'}[e.target.value];form.elements.name.value=name;form.elements.slug.value=slugify(name);return;}if(e.target.dataset.websiteFilter==='business'){businessFilter=e.target.value;renderGallery();document.querySelector('[data-website-filter="business"]')?.focus();return;}if(!e.target.hasAttribute('data-website-files')||busy)return;try{for(const f of e.target.files){const target=sharedLayout()&&sourceScope==='page'?pageFile(selectedPage,f.name.split('.').pop()):f.name;if(!editableFiles().includes(target))throw Error('Choose HTML, CSS or JavaScript files for the selected scope.');if(f.size>160000)throw Error('This source file is too large.');data.draft.files[target]=await f.text();}dirty=true;render();toast('Files loaded into the editor. Save to update the preview.');}catch(error){toast(error.message);}});
 window.addEventListener('message',async e=>{const frame=document.querySelector('.website-preview iframe');if(!frame||e.source!==frame.contentWindow||e.data?.channel!==previewChannel)return;if(e.data.type==='website-page-navigation'){if(busy)return;busy=true;freeze(true);try{await selectPage(e.data.page,String(e.data.fragment||''));}catch(error){toast(error.message);}finally{busy=false;freeze(false);}return;}if(e.data.type!=='website-preview-report')return;previewReport=e.data;const status=document.querySelector('.website-preview-health');if(status)status.textContent=e.data.errors?.length?'Preview issue: '+String(e.data.errors[0]).slice(0,250):e.data.missingImages?'Some images did not load.':e.data.overflow?'This layout is wider than the preview.':'Preview loaded · Interactions are ready to try';});
 document.addEventListener('keydown',e=>{if(e.target.matches('[data-action="website-publish-tab"],[data-action="website-materials-tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...e.target.closest('[role="tablist"]').querySelectorAll('[role="tab"]')],index=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();return;}const gallery=document.getElementById('website-gallery');if(!gallery)return;if(e.key==='Escape'){e.preventDefault();galleryOpen=false;renderGallery();}if(e.key==='Tab'){const nodes=[...gallery.querySelectorAll('button:not([disabled]),select,iframe.website-full-example')];const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 return {page,load,action,submit,active,afterRender,save,destroyCode};
}
